//! The roles and what each account was given: `roles`, `user_roles` and
//! `user_permissions` (ADR 0007 §3, ADR 0009).
//!
//! The role-to-permission mapping is not stored: it is a constant in
//! `src/domain/authz.rs`, so every change to it is a reviewed code change
//! (ADR 0007 §3). These tables hold only the four roles and, per account,
//! its roles and its extra grants („Egyéni jogosultságok”).
//!
//! - `roles` holds the four roles with backend1's ids, seeded here: 1
//!   `writer`, 2 `secretary`, 3 `supervisor`, 4 `admin`. Its `id` is
//!   `bigint GENERATED BY DEFAULT AS IDENTITY`, the definition that
//!   ADR 0009's primary-key rule 1 gives every entity table (Loco's
//!   `ColType::PkAuto` renders the same). Asked "Should `roles.id` stay an
//!   identity column, or become a plain `bigint` key that every insert must
//!   name?", the maintainer answered "Keep the identity column (as built)"
//!   on 2026-11-01 (research: DECISIONS R27 (D126)). `BY DEFAULT` takes the
//!   explicit ids, which the code names (`crate::domain::authz::Role`), and
//!   the migration then sets the identity sequence past the highest of them,
//!   so a row inserted without an id can never take a seeded one (the aim of
//!   ADR 0009 rule 3). A new role still arrives as a migration that inserts
//!   its row with its id, and that migration sets the sequence past it too:
//!   otherwise the next insert without an id fails on `roles_pkey`, and so
//!   does `a_role_inserted_without_an_id_never_takes_a_seeded_one` in
//!   `tests/migration/authz.rs`. Like the join tables, `roles` has no audit
//!   columns (ADR 0009, "Columns per table").
//! - `user_roles (user_id, role_id)` and `user_permissions (user_id,
//!   permission)` are join tables with a composite primary key and no
//!   surrogate id (ADR 0009). Both cascade from `users`, so a link never
//!   outlives its account, and `user_roles.role_id` restricts, so a role that
//!   an account holds cannot be removed (ADR 0009, "Constraints"). Accounts
//!   are anonymised rather than deleted, and anonymisation removes the links
//!   itself (ADR 0011 §6); the cascade only keeps the database consistent.
//! - `user_permissions.permission` is `text` with a CHECK that lists exactly
//!   the sixteen permission names of ADR 0007 §1. `edit newsletter` and
//!   `manage backups` are not among them: the maintainer confirmed on
//!   2026-10-25 that neither is created (ADR 0007, follow-up points 1-3;
//!   research: DECISIONS R9 (D06)). A PostgreSQL `ENUM` is not used
//!   (ADR 0009, "Column types").
//!
//! Every foreign-key column has an index (ADR 0009): `user_id` is the
//! leading column of each primary key, whose index serves it, and
//! `user_roles.role_id` gets its own.
//!
//! The lists here are written out, not taken from `src/domain/authz.rs`:
//! a migration records the schema of its day and must not change when the
//! code does, and the `migration` crate cannot depend on the application
//! crate anyway. `tests/migration/authz.rs` holds the seeded rows and the
//! CHECK equal to `Role::ALL` and `Permission::ALL`, so adding a role or a
//! permission is a new migration together with the code change (ADR 0007
//! §3).
//!
//! Loco's `create_table` cannot write these tables: it always adds the
//! `created_at` and `updated_at` pair, which ADR 0009 gives neither join
//! tables nor `roles`. So [`STATEMENTS`] is plain SQL, with `snake_case`
//! names that need no quoting.

use sea_orm_migration::prelude::*;

/// Creates `roles` with its four rows, `user_roles` and `user_permissions`.
#[derive(DeriveMigrationName)]
pub struct Migration;

/// The statements of [`Migration::up`], in order.
///
/// Constraint names follow PostgreSQL's own `<table>_<column>_<suffix>`
/// pattern (`_pkey`, `_key`, `_fkey`, `_idx`), as the `users` migration's
/// do. The CHECK gets the descriptive name `user_permissions_permission_known`
/// instead of PostgreSQL's `user_permissions_permission_check`, so a refused
/// row's error says which rule refused it.
const STATEMENTS: &[&str] = &[
    "CREATE TABLE roles (\
         id bigint GENERATED BY DEFAULT AS IDENTITY NOT NULL, \
         name text NOT NULL, \
         CONSTRAINT roles_pkey PRIMARY KEY (id), \
         CONSTRAINT roles_name_key UNIQUE (name))",
    // backend1's ids and names (ADR 0007 §3), in id order.
    "INSERT INTO roles (id, name) VALUES \
         (1, 'writer'), (2, 'secretary'), (3, 'supervisor'), (4, 'admin')",
    // An explicit id does not advance an identity sequence, so without this
    // the first row inserted without an id would get 1 and fail on
    // `roles_pkey`. `setval` with the default `is_called = true` makes the
    // next value max(id) + 1, here 5. It changes the sequence's current
    // value only, not its options, which the schema guard compares.
    "SELECT setval(pg_get_serial_sequence('roles', 'id'), (SELECT max(id) FROM roles))",
    "CREATE TABLE user_roles (\
         user_id bigint NOT NULL, \
         role_id bigint NOT NULL, \
         CONSTRAINT user_roles_pkey PRIMARY KEY (user_id, role_id), \
         CONSTRAINT user_roles_user_id_fkey FOREIGN KEY (user_id) \
             REFERENCES users (id) ON DELETE CASCADE, \
         CONSTRAINT user_roles_role_id_fkey FOREIGN KEY (role_id) \
             REFERENCES roles (id) ON DELETE RESTRICT)",
    "CREATE INDEX user_roles_role_id_idx ON user_roles (role_id)",
    // The sixteen names of ADR 0007 §1, in the order of its table.
    "CREATE TABLE user_permissions (\
         user_id bigint NOT NULL, \
         permission text NOT NULL, \
         CONSTRAINT user_permissions_pkey PRIMARY KEY (user_id, permission), \
         CONSTRAINT user_permissions_user_id_fkey FOREIGN KEY (user_id) \
             REFERENCES users (id) ON DELETE CASCADE, \
         CONSTRAINT user_permissions_permission_known CHECK (permission IN (\
             'edit posts', 'publish posts', 'edit labels', 'edit authors', \
             'edit events', 'edit canteens', 'edit colleagues', 'edit users', \
             'edit pages', 'edit menu', 'manage media', 'view logs', \
             'edit notices', 'edit banners', 'edit site settings', 'edit diaktoll')))",
];

/// The statements of [`Migration::down`], in order: the join tables first,
/// because they reference `roles`.
const DROP_STATEMENTS: &[&str] = &[
    "DROP TABLE user_permissions",
    "DROP TABLE user_roles",
    "DROP TABLE roles",
];

#[async_trait::async_trait]
impl MigrationTrait for Migration {
    async fn up(&self, m: &SchemaManager) -> Result<(), DbErr> {
        let db = m.get_connection();
        for statement in STATEMENTS {
            db.execute_unprepared(statement).await?;
        }
        Ok(())
    }

    /// Drops the three tables, and with them every role and grant.
    async fn down(&self, m: &SchemaManager) -> Result<(), DbErr> {
        let db = m.get_connection();
        for statement in DROP_STATEMENTS {
            db.execute_unprepared(statement).await?;
        }
        Ok(())
    }
}
